def compress(s: str) -> str:
    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s) + 1):
        if i == len(s) or s[i] != s[i-1]:
            result.append(s[i-1] + (str(count) if count > 1 else ""))
            count = 1
        else:
            count += 1
    return ''.join(result)
```

