def second_largest(nums: list[int]) -> int | None:
    if len(nums) < 2:
        return None

    first = second = float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
            second = num

    return second if second != float('-inf') else None
```

