def valid_brackets(s: str) -> bool:
    bracket_map = {")": "(", "]": "[", "}": "{"}
    open_brackets = set(["(", "[", "{"])
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in bracket_map:
            if stack and stack[-1] == bracket_map[char]:
                stack.pop()
            else:
                return False
    return not stack
```

